//! Work queue: items the human or an AI produces, moved through statuses.
//! Stored as JSON next to the task list. Shape per item:
//! `{id, title, kind, source, node, status, payload, created, updated}`.

use crate::now;
use serde::{Deserialize, Serialize};
use serde_json::Value;

pub const STATUSES: [&str; 5] = ["queued", "running", "review", "done", "failed"];

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Item {
    pub id: u64,
    pub title: String,
    /// `todo` (human) or `ai` (generated by a graph step).
    #[serde(default = "default_kind")]
    pub kind: String,
    /// Where it came from: `import:<file>`, `mcp`, `graph:<node>`, `ui`.
    #[serde(default)]
    pub source: String,
    /// Skill-graph node that produced or owns this item, if any.
    #[serde(default)]
    pub node: Option<String>,
    #[serde(default = "default_status")]
    pub status: String,
    #[serde(default)]
    pub payload: Value,
    pub created: u64,
    pub updated: u64,
}

fn default_kind() -> String {
    "todo".into()
}
fn default_status() -> String {
    "queued".into()
}

pub fn enqueue(items: &mut Vec<Item>, title: &str, kind: &str, source: &str, node: Option<String>, payload: Value) -> Item {
    let id = items.iter().map(|i| i.id).max().unwrap_or(0) + 1;
    let t = now();
    let item = Item {
        id,
        title: title.trim().to_string(),
        kind: kind.to_string(),
        source: source.to_string(),
        node,
        status: "queued".into(),
        payload,
        created: t,
        updated: t,
    };
    items.push(item.clone());
    item
}

pub fn set_status(items: &mut [Item], id: u64, status: &str) -> bool {
    if !STATUSES.contains(&status) {
        return false;
    }
    match items.iter_mut().find(|i| i.id == id) {
        Some(i) => {
            i.status = status.to_string();
            i.updated = now();
            true
        }
        None => false,
    }
}

/// Atomically take the oldest `queued` item for `node` and mark it `running`.
/// `agent` is recorded in the payload so a client can see who holds it.
pub fn claim(items: &mut [Item], node: &str, agent: &str) -> Option<Item> {
    let item = items
        .iter_mut()
        .filter(|i| i.status == "queued" && i.node.as_deref() == Some(node))
        .min_by_key(|i| i.created)?;
    item.status = "running".into();
    item.updated = now();
    if let Some(obj) = item.payload.as_object_mut() {
        obj.insert("agent".into(), serde_json::Value::String(agent.into()));
    } else {
        item.payload = serde_json::json!({"agent": agent});
    }
    Some(item.clone())
}
